<script lang="ts">
  /**
   * front(사용자 화면) 전용 — BI(브랜드 로고 마크) 기반 데이터 호출 지연 감지형 로딩 애니메이션.
   *
   * "지연 감지형"인 이유: loading=true가 되는 즉시 표시하지 않고 `delay`(기본 400ms) 동안
   * 대기 후에도 여전히 로딩 중이면 그때 표시한다 — 빠르게 끝나는 호출(수백ms 이내)에서
   * 화면이 깜빡이는 것을 방지한다. 한번 표시되면 최소 `minDuration`(기본 400ms) 동안은
   * 유지한 뒤 사라진다 — 로딩이 막 끝난 순간 표시됐다가 즉시 사라지는 깜빡임도 방지한다.
   *
   * CMS의 nav-loading-overlay(cms/+layout.svelte)와 동일한 모션 언어(펄스 1.8s ease-in-out
   * infinite + 도트 바운스 1.2s ease-in-out infinite, 0.18s 스태거)를 재사용 — 신규 easing
   * 임의 창작 없음. 색상만 front 팔레트(--cs-red-badge)로 전환(--cs-orange는 front에서
   * "로고 전용" 제약 토큰이라 버튼·장식 요소에 사용 금지, uiux-index.md).
   */
  interface Props {
    loading: boolean
    delay?: number
    minDuration?: number
    label?: string
  }
  let { loading, delay = 400, minDuration = 400, label = '불러오는 중' }: Props = $props()

  let visible = $state(false)
  let showTimer: ReturnType<typeof setTimeout> | null = null
  let hideTimer: ReturnType<typeof setTimeout> | null = null
  let shownAt = 0

  $effect(() => {
    if (loading) {
      if (hideTimer) {
        clearTimeout(hideTimer)
        hideTimer = null
      }
      if (!visible && !showTimer) {
        showTimer = setTimeout(() => {
          visible = true
          shownAt = Date.now()
          showTimer = null
        }, delay)
      }
    } else {
      if (showTimer) {
        clearTimeout(showTimer)
        showTimer = null
      }
      if (visible) {
        const remaining = Math.max(0, minDuration - (Date.now() - shownAt))
        hideTimer = setTimeout(() => {
          visible = false
          hideTimer = null
        }, remaining)
      }
    }
  })

  $effect(() => {
    return () => {
      if (showTimer) clearTimeout(showTimer)
      if (hideTimer) clearTimeout(hideTimer)
    }
  })
</script>

