<style>
  .cs-loading-overlay {
    position: fixed;
    inset: 0;
    z-index: 9999;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 20px;
    background: rgba(16, 11, 50, 0.72);
    backdrop-filter: blur(3px);
    animation: cs-loading-overlay-in 0.18s ease-out;
  }

  /* 모바일 기본값 */
  .cs-loading-bi {
    width: 96px;
    height: auto;
    animation: cs-loading-pulse 1.8s ease-in-out infinite;
  }
  .cs-loading-dots span {
    width: 6px;
    height: 6px;
  }

  /* PC 반응형(≥768px) — 모바일보다 크게, 도트 간격도 넓게 */
  @media (min-width: 768px) {
    .cs-loading-bi { width: 150px; }
    .cs-loading-overlay { gap: 28px; }
    .cs-loading-dots { gap: 10px; }
    .cs-loading-dots span { width: 8px; height: 8px; }
  }

  .cs-loading-dots {
    display: flex;
    gap: 8px;
    align-items: center;
  }
  .cs-loading-dots span {
    display: block;
    border-radius: 50%;
    background: var(--cs-red-badge);
    animation: cs-loading-dot-bounce 1.2s ease-in-out infinite;
  }
  .cs-loading-dots span:nth-child(2) { animation-delay: 0.18s; }
  .cs-loading-dots span:nth-child(3) { animation-delay: 0.36s; }

  .cs-loading-sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }

  @keyframes cs-loading-overlay-in {
    from { opacity: 0; }
    to   { opacity: 1; }
  }
  @keyframes cs-loading-pulse {
    0%, 100% { opacity: 1;   transform: scale(1); }
    50%      { opacity: 0.6; transform: scale(0.92); }
  }
  @keyframes cs-loading-dot-bounce {
    0%, 80%, 100% { transform: translateY(0);    opacity: 0.35; }
    40%           { transform: translateY(-7px); opacity: 1; }
  }
</style>
